begin;

create temporary table coding_question_seed (
  collection_slug text not null, slug text not null, title text not null,
  problem_statement text not null, difficulty text not null, topic_tags text[] not null,
  constraints jsonb not null, examples jsonb not null, starter_code_by_language jsonb not null,
  points integer not null, seed_order integer not null
) on commit drop;

insert into coding_question_seed
select r.collection_slug, r.slug, r.title, r.problem_statement, r.difficulty,
       array(select jsonb_array_elements_text(r.topic_tags)), r.constraints, r.examples,
       r.starter_code_by_language, r.points, r.seed_order
from jsonb_to_recordset($seed$[{"collection_slug":"java-fundamentals","slug":"rotate-array-right","title":"Rotate an Array Right","problem_statement":"Return a new array rotated right by k positions; reduce k modulo the array length, leave the input unchanged, and return an empty array when the input is empty.","difficulty":"Easy","topic_tags":["Arrays","Modulo"],"constraints":["0 <= values.length <= 100000","k >= 0"],"examples":[{"input":"[1,2,3,4,5], k=2","output":"[4,5,1,2,3]"},{"input":"[7], k=19","output":"[7]"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int[] rotateRight(int[] values, int k) {\n    // Implement the described algorithm and return its result.\n    return new int[0];\n  }\n}"},"points":100,"seed_order":1},{"collection_slug":"java-fundamentals","slug":"balanced-delimiters","title":"Validate Delimiter Nesting","problem_statement":"Return true when every parenthesis, bracket, and brace is matched in the correct nesting order; ignore other characters.","difficulty":"Easy","topic_tags":["Stack","Parsing"],"constraints":["0 <= text.length() <= 100000","Only (), [], and {} are delimiters"],"examples":[{"input":"{a[(b)]}","output":"true"},{"input":"([)]","output":"false"}],"starter_code_by_language":{"Java":"public class Solution {\n  static boolean hasBalancedDelimiters(String text) {\n    // Implement the described algorithm and return its result.\n    return false;\n  }\n}"},"points":100,"seed_order":2},{"collection_slug":"java-fundamentals","slug":"first-unique-character","title":"Find the First Unique Character","problem_statement":"Return the index of the first character occurring once, or -1. Matching is case-sensitive and input contains lowercase English letters.","difficulty":"Easy","topic_tags":["Strings","Frequency Counting"],"constraints":["0 <= text.length() <= 100000","text contains lowercase English letters"],"examples":[{"input":"swiss","output":"1"},{"input":"aabb","output":"-1"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int firstUniqueIndex(String text) {\n    // Implement the described algorithm and return its result.\n    return -1;\n  }\n}"},"points":100,"seed_order":3},{"collection_slug":"java-fundamentals","slug":"merge-intervals-java","title":"Merge Overlapping Intervals","problem_statement":"Sort intervals by start and merge intervals that overlap or touch at an endpoint. Return a new array without changing the input.","difficulty":"Medium","topic_tags":["Intervals","Sorting"],"constraints":["0 <= intervals.length <= 100000","Each interval is [start,end] and start <= end"],"examples":[{"input":"[[1,3],[2,6],[8,10],[10,12]]","output":"[[1,6],[8,12]]"},{"input":"[[4,4],[5,7]]","output":"[[4,4],[5,7]]"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int[][] mergeIntervals(int[][] intervals) {\n    // Implement the described algorithm and return its result.\n    return new int[0][0];\n  }\n}"},"points":150,"seed_order":4},{"collection_slug":"java-fundamentals","slug":"spiral-matrix-order","title":"Read a Matrix in Spiral Order","problem_statement":"Return every matrix value in clockwise spiral order, starting at the top-left. Return an empty list if either dimension is zero.","difficulty":"Medium","topic_tags":["Matrices","Boundary Traversal"],"constraints":["0 <= rows, columns <= 500","Rows have equal length"],"examples":[{"input":"[[1,2,3],[4,5,6],[7,8,9]]","output":"[1,2,3,6,9,8,7,4,5]"},{"input":"[[1,2,3,4]]","output":"[1,2,3,4]"}],"starter_code_by_language":{"Java":"public class Solution {\n  static java.util.List<Integer> spiralOrder(int[][] matrix) {\n    // Implement the described algorithm and return its result.\n    return new java.util.ArrayList<>();\n  }\n}"},"points":150,"seed_order":5},{"collection_slug":"java-fundamentals","slug":"pascal-row-java","title":"Generate a Pascal Triangle Row","problem_statement":"Return row n of Pascal triangle, where row zero is [1]; each entry is the sum of the two entries above it.","difficulty":"Easy","topic_tags":["Combinatorics","Lists"],"constraints":["0 <= n <= 60","All values fit in long"],"examples":[{"input":"4","output":"[1,4,6,4,1]"},{"input":"6","output":"[1,6,15,20,15,6,1]"}],"starter_code_by_language":{"Java":"public class Solution {\n  static java.util.List<Long> pascalRow(int n) {\n    // Implement the described algorithm and return its result.\n    return new java.util.ArrayList<>();\n  }\n}"},"points":100,"seed_order":6},{"collection_slug":"java-fundamentals","slug":"evaluate-postfix-expression","title":"Evaluate a Postfix Expression","problem_statement":"Evaluate a valid integer postfix expression using binary +, -, *, and /. Division truncates toward zero.","difficulty":"Medium","topic_tags":["Stack","Expression Evaluation"],"constraints":["1 <= tokens.length <= 10000","Intermediate values fit in int","Division by zero does not occur"],"examples":[{"input":"[2,1,+,3,*]","output":"9"},{"input":"[-7,2,/]","output":"-3"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int evaluatePostfix(String[] tokens) {\n    // Implement the described algorithm and return its result.\n    return 0;\n  }\n}"},"points":150,"seed_order":7},{"collection_slug":"java-fundamentals","slug":"sliding-window-maximum","title":"Maximum of Each Fixed Window","problem_statement":"For each contiguous window of width k, return its maximum in left-to-right window order.","difficulty":"Hard","topic_tags":["Deque","Sliding Window"],"constraints":["1 <= values.length <= 200000","1 <= k <= values.length"],"examples":[{"input":"[1,3,-1,-3,5,3,6,7], k=3","output":"[3,3,5,5,6,7]"},{"input":"[4,2], k=1","output":"[4,2]"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int[] windowMaximum(int[] values, int k) {\n    // Implement the described algorithm and return its result.\n    return new int[0];\n  }\n}"},"points":200,"seed_order":8},{"collection_slug":"java-fundamentals","slug":"compare-version-numbers","title":"Compare Version Numbers","problem_statement":"Compare dot-separated nonnegative integer components numerically, treating missing trailing components as zero; return -1, 0, or 1.","difficulty":"Medium","topic_tags":["Strings","Parsing"],"constraints":["1 <= version.length() <= 1000","Components contain decimal digits only"],"examples":[{"input":"1.02, 1.2.0","output":"0"},{"input":"1.0.9, 1.0.11","output":"-1"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int compareVersions(String first, String second) {\n    // Implement the described algorithm and return its result.\n    return 0;\n  }\n}"},"points":150,"seed_order":9},{"collection_slug":"java-fundamentals","slug":"normalize-file-path","title":"Normalize an Absolute Unix Path","problem_statement":"Remove empty and dot segments, resolve parent segments without moving above root, and return a normalized absolute slash-separated path.","difficulty":"Medium","topic_tags":["Strings","Stack"],"constraints":["path starts with /","0 <= path.length() <= 100000"],"examples":[{"input":"/a//b/../c/","output":"/a/c"},{"input":"/../../x","output":"/x"}],"starter_code_by_language":{"Java":"public class Solution {\n  static String normalizePath(String path) {\n    // Implement the described algorithm and return its result.\n    return \"/\";\n  }\n}"},"points":150,"seed_order":10},{"collection_slug":"java-fundamentals","slug":"minimum-window-substring-java","title":"Minimum Window Substring","problem_statement":"Return the shortest source substring containing each target character with its multiplicity. On equal lengths choose the earliest start; return empty text if impossible.","difficulty":"Hard","topic_tags":["Strings","Sliding Window"],"constraints":["1 <= target.length() <= 100000","0 <= source.length() <= 100000","Characters are ASCII"],"examples":[{"input":"source=ADOBECODEBANC, target=ABC","output":"BANC"},{"input":"source=a, target=aa","output":"\"\""}],"starter_code_by_language":{"Java":"public class Solution {\n  static String minWindow(String source, String target) {\n    // Implement the described algorithm and return its result.\n    return \"\";\n  }\n}"},"points":200,"seed_order":11},{"collection_slug":"java-fundamentals","slug":"edit-distance-java","title":"Minimum Edit Distance","problem_statement":"Return the fewest single-character insertions, deletions, and substitutions needed to transform first into second.","difficulty":"Medium","topic_tags":["Dynamic Programming","Strings"],"constraints":["0 <= first.length(), second.length() <= 1000","Both input strings contain lowercase English letters"],"examples":[{"input":"horse, ros","output":"3"},{"input":"intention, execution","output":"5"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int editDistance(String first, String second) {\n    // Implement the described algorithm and return its result.\n    return 0;\n  }\n}"},"points":150,"seed_order":12},{"collection_slug":"java-fundamentals","slug":"coin-change-minimum","title":"Minimum Coins for an Amount","problem_statement":"Return the smallest number of unlimited-use coins that sum to amount, or -1 if no combination exists.","difficulty":"Medium","topic_tags":["Dynamic Programming","Arrays"],"constraints":["1 <= coins.length <= 100","1 <= coins[i] <= 10000","0 <= amount <= 100000"],"examples":[{"input":"coins=[1,2,5], amount=11","output":"3"},{"input":"coins=[2], amount=3","output":"-1"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int minimumCoins(int[] coins, int amount) {\n    // Implement the described algorithm and return its result.\n    return -1;\n  }\n}"},"points":150,"seed_order":13},{"collection_slug":"java-fundamentals","slug":"word-break-possible","title":"Segment Text into Dictionary Words","problem_statement":"Return whether text can be split into dictionary words; words may be reused. Empty text is segmentable.","difficulty":"Medium","topic_tags":["Dynamic Programming","HashSet"],"constraints":["0 <= text.length() <= 10000","Dictionary words are nonempty lowercase strings"],"examples":[{"input":"text=leetcode, words=[leet,code]","output":"true"},{"input":"text=catsandog, words=[cats,dog,sand,and,cat]","output":"false"}],"starter_code_by_language":{"Java":"public class Solution {\n  static boolean wordBreak(String text, java.util.Set<String> dictionary) {\n    // Implement the described algorithm and return its result.\n    return false;\n  }\n}"},"points":150,"seed_order":14},{"collection_slug":"java-fundamentals","slug":"count-islands-grid","title":"Count Islands in a Grid","problem_statement":"Count connected groups of land cells, where land is 1 and connectivity is up, down, left, or right. Do not mutate the grid.","difficulty":"Medium","topic_tags":["Graphs","Grid Search"],"constraints":["0 <= rows, columns <= 500","Cells contain only 0 or 1"],"examples":[{"input":"[[1,1,0],[0,1,0],[1,0,1]]","output":"3"},{"input":"[[1,1],[1,1]]","output":"1"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int countIslands(char[][] grid) {\n    // Implement the described algorithm and return its result.\n    return 0;\n  }\n}"},"points":150,"seed_order":15},{"collection_slug":"java-fundamentals","slug":"course-order-java","title":"Return a Course Schedule","problem_statement":"Return a topological ordering of courses given [course, prerequisite] pairs. Among currently available courses, always choose the smallest id; return [] when a cycle exists.","difficulty":"Medium","topic_tags":["Graphs","Topological Sort"],"constraints":["0 <= courseCount <= 200000","Prerequisite pairs are valid course ids"],"examples":[{"input":"n=4, pairs=[[1,0],[2,0],[3,1],[3,2]]","output":"[0,1,2,3]"},{"input":"n=2, pairs=[[0,1],[1,0]]","output":"[]"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int[] courseOrder(int courseCount, int[][] prerequisites) {\n    // Implement the described algorithm and return its result.\n    return new int[0];\n  }\n}"},"points":150,"seed_order":16},{"collection_slug":"java-fundamentals","slug":"shortest-grid-path","title":"Shortest Path in a Binary Grid","problem_statement":"Return the fewest four-directional moves from start to goal through zero-valued cells, or -1 if no route exists.","difficulty":"Medium","topic_tags":["Breadth-First Search","Grid"],"constraints":["1 <= rows, columns <= 1000","Start and goal are in bounds and traversable"],"examples":[{"input":"grid=[[0,0,1],[1,0,0]], start=[0,0], goal=[1,2]","output":"3"},{"input":"grid=[[0,1],[1,0]], start=[0,0], goal=[1,1]","output":"-1"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int shortestGridPath(int[][] grid, int[] start, int[] goal) {\n    // Implement the described algorithm and return its result.\n    return -1;\n  }\n}"},"points":150,"seed_order":17},{"collection_slug":"java-fundamentals","slug":"dijkstra-distances","title":"Single-Source Shortest Paths","problem_statement":"Return shortest distances from source in a directed weighted graph; use -1 for unreachable vertices. Edges are [from,to,weight].","difficulty":"Hard","topic_tags":["Graphs","Dijkstra"],"constraints":["1 <= vertexCount <= 100000","Edge weights are nonnegative integers","Distances fit in long","0 <= source < vertexCount and every edge endpoint is in range"],"examples":[{"input":"n=4, edges=[[0,1,4],[0,2,1],[2,1,2],[1,3,1]], source=0","output":"[0,3,1,4]"},{"input":"n=3, edges=[[0,1,5]], source=2","output":"[-1,-1,0]"}],"starter_code_by_language":{"Java":"public class Solution {\n  static long[] shortestDistances(int vertexCount, int[][] edges, int source) {\n    // Implement the described algorithm and return its result.\n    return new long[0];\n  }\n}"},"points":200,"seed_order":18},{"collection_slug":"java-fundamentals","slug":"range-sum-queries","title":"Answer Static Range-Sum Queries","problem_statement":"For each inclusive index query [left,right], return the sum of the corresponding values. Sums are computed in 64-bit arithmetic.","difficulty":"Easy","topic_tags":["Prefix Sums","Arrays"],"constraints":["1 <= values.length <= 200000","0 <= left <= right < values.length"],"examples":[{"input":"values=[2,-1,4,6], queries=[[0,2],[1,3]]","output":"[5,9]"},{"input":"values=[5], queries=[[0,0]]","output":"[5]"}],"starter_code_by_language":{"Java":"public class Solution {\n  static long[] rangeSums(int[] values, int[][] queries) {\n    // Implement the described algorithm and return its result.\n    return new long[0];\n  }\n}"},"points":100,"seed_order":19},{"collection_slug":"java-fundamentals","slug":"minimum-meeting-rooms","title":"Minimum Meeting Rooms","problem_statement":"Return the fewest rooms needed for half-open intervals [start,end]; a meeting ending at t frees its room for another starting at t.","difficulty":"Medium","topic_tags":["Intervals","Priority Queue"],"constraints":["0 <= meetings.length <= 100000","start < end for every interval"],"examples":[{"input":"[[0,30],[5,10],[15,20]]","output":"2"},{"input":"[[1,4],[4,7],[7,8]]","output":"1"}],"starter_code_by_language":{"Java":"public class Solution {\n  static int minimumMeetingRooms(int[][] meetings) {\n    // Implement the described algorithm and return its result.\n    return 0;\n  }\n}"},"points":150,"seed_order":20}]$seed$) as r(
  collection_slug text, slug text, title text, problem_statement text, difficulty text,
  topic_tags jsonb, constraints jsonb, examples jsonb, starter_code_by_language jsonb,
  points integer, seed_order integer
);

do $$
begin
  if (select count(*) from coding_question_seed) <> 20 then raise exception 'Java seed must contain exactly 20 records'; end if;
  if (select count(distinct slug) from coding_question_seed) <> 20 then raise exception 'Java slugs must be distinct'; end if;
  if (select count(distinct title) from coding_question_seed) <> 20 or (select count(distinct problem_statement) from coding_question_seed) <> 20 then raise exception 'Question titles and statements must be distinct'; end if;
  if exists (select 1 from coding_question_seed where collection_slug <> 'java-fundamentals' or slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(btrim(title)) not between 1 and 200 or char_length(btrim(problem_statement)) not between 1 and 12000 or difficulty not in ('Easy','Medium','Hard') or cardinality(topic_tags)=0 or jsonb_typeof(constraints)<>'array' or jsonb_array_length(constraints)<2 or jsonb_typeof(examples)<>'array' or jsonb_array_length(examples)<2 or jsonb_typeof(starter_code_by_language)<>'object' or jsonb_object_length(starter_code_by_language)<>1 or not (starter_code_by_language ? 'Java') or points not between 0 and 1000) then raise exception 'Invalid Java seed record'; end if;
  if exists (select 1 from coding_question_seed s cross join lateral jsonb_array_elements(s.examples) e where coalesce(e->>'input','')='' or coalesce(e->>'output','')='' or e->>'output' in ('[null]','null','')) then raise exception 'Java examples are incomplete or placeholders'; end if;
  if exists (select 1 from coding_question_seed where slug in ('palindrome-check','fizz-buzz','sum-of-array','factorial','max-subarray-sum','second-largest-distinct-java','sum-decimal-digits-java')) then raise exception 'Existing Java slug included'; end if;
  if exists (select 1 from coding_question_seed where problem_statement ilike '%TODO%' or title ilike '%placeholder%' or starter_code_by_language::text ilike '%pass%') then raise exception 'Placeholder content detected'; end if;
  if not exists (select 1 from public.coding_test_sets where slug='java-fundamentals' and supported_languages='["Java"]'::jsonb) then raise exception 'Java collection missing or has unsupported languages'; end if;
end $$;

with numbered as (
  select seed.*, collection.id as collection_id,
         (select coalesce(max(q.question_order),0) from public.coding_questions q where q.collection_id=collection.id)
           + row_number() over (order by seed.seed_order)::integer as question_order
  from coding_question_seed seed
  join public.coding_test_sets collection on collection.slug=seed.collection_slug
)
insert into public.coding_questions (collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,publication_status,question_order)
select collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,'published',question_order
from numbered
on conflict (collection_id,slug) do nothing;

insert into public.coding_test_cases (question_id,case_order,test_input,expected_output,visibility)
select question.id, example.ordinality::integer, example.value->>'input', example.value->>'output', 'visible'
from coding_question_seed seed
join public.coding_test_sets collection on collection.slug=seed.collection_slug
join public.coding_questions question on question.collection_id=collection.id and question.slug=seed.slug
cross join lateral jsonb_array_elements(seed.examples) with ordinality as example(value,ordinality)
on conflict (question_id,case_order) do nothing;

commit;
